ASN.label_rule_source:
@model_validator(mode="after")
def compute_label(self) -> Self:
    # Use name and ASN string if available
    if self.name:
        self.nodeLabel = f"{self.asn_str} - {self.name}"
    else:
        self.nodeLabel = self.asn_str
    return self

